#include <bits/stdc++.h>
using namespace std;

int main() {
    const long long MOD = 1000000007;
    string s;
    int n, x, y;
    cin >> s >> n >> x >> y;
    if (x > n || y > n) {
        puts("0");
        return 0;
    }
    // f[p]: distinct valid subsequences (including empty) ending at position p.
    vector<long long> f(n + 1, 0), added(n + 1);
    vector<vector<long long>> last(2, vector<long long>(n + 1, 0));
    f[x] = 1;
    for (char ch : s) {
        int dir = ch == 'r';
        for (int j = 0; j <= n; j++) {
            if (dir) added[j] = j > 0 ? f[j - 1] : 0;
            else added[j] = j < n ? f[j + 1] : 0;
        }
        // Strings already produced by the previous occurrence of ch are subtracted once.
        for (int j = 0; j <= n; j++) f[j] = ((f[j] + added[j] - last[dir][j]) % MOD + MOD) % MOD;
        last[dir] = added;
    }
    printf("%lld\n", f[y]);
}

import java.io.*;
import java.util.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int start = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, start, pos - start);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] >= '0' && buf[pos] <= '9') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        final long MOD = 1000000007L;
        String s = next();
        int n = nextInt(), x = nextInt(), y = nextInt();
        if (x > n || y > n) {
            System.out.println(0);
            return;
        }
        // f[p]: distinct valid subsequences (including empty) ending at position p.
        long[] f = new long[n + 1];
        long[][] last = new long[2][n + 1];
        f[x] = 1;
        for (int c = 0; c < s.length(); c++) {
            int dir = s.charAt(c) == 'r' ? 1 : 0;
            long[] added = new long[n + 1];
            for (int j = 0; j <= n; j++) {
                if (dir == 1) added[j] = j > 0 ? f[j - 1] : 0;
                else added[j] = j < n ? f[j + 1] : 0;
            }
            // Strings already produced by the previous occurrence of this letter are subtracted once.
            for (int j = 0; j <= n; j++) f[j] = ((f[j] + added[j] - last[dir][j]) % MOD + MOD) % MOD;
            last[dir] = added;
        }
        System.out.println(f[y]);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func skip() {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
}

func next() string {
	skip()
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

func nextInt() int64 {
	skip()
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	const MOD = 1000000007
	s := next()
	n, x, y := int(nextInt()), int(nextInt()), int(nextInt())
	if x > n || y > n {
		fmt.Println(0)
		return
	}
	// f[p]: distinct valid subsequences (including empty) ending at position p.
	f := make([]int64, n+1)
	last := [2][]int64{make([]int64, n+1), make([]int64, n+1)}
	f[x] = 1
	for c := 0; c < len(s); c++ {
		dir := 0
		if s[c] == 'r' {
			dir = 1
		}
		added := make([]int64, n+1)
		for j := 0; j <= n; j++ {
			if dir == 1 && j > 0 {
				added[j] = f[j-1]
			} else if dir == 0 && j < n {
				added[j] = f[j+1]
			}
		}
		// Strings already produced by the previous occurrence of this letter are subtracted once.
		for j := 0; j <= n; j++ {
			f[j] = ((f[j]+added[j]-last[dir][j])%MOD + MOD) % MOD
		}
		last[dir] = added
	}
	fmt.Println(f[y])
}
